/**
 * Field hints, the per-field reference and the configuration guide for
 * /workshopconfig/:id.
 *
 * Every line was written by tracing the field through the EiFlix user app (the
 * Flutter project) and checking what it actually changes for a learner — not
 * from the field's name. Where the app ignores a setting, it says so.
 *
 * House rule: no stored field name or code identifier appears in any hint,
 * label or guide text. Settings are referred to by their on-screen label.
 */

export interface FieldNote {
  /** Control name — used to look the note up, never displayed. */
  key: string;
  /** The label as it appears on the configuration screen. */
  label: string;
  /** Which tab it lives on. */
  group: 'Enrollment page' | 'Settings' | 'Challenges';
  /** The one-liner shown under the field. */
  hint: string;
  /** The longer explanation, shown in the guide's reference. */
  detail: string;
  /** True when nothing in the user app reads this setting. */
  unused: boolean;
}

/** Every traced setting, sorted by tab then label. */
export const FIELD_REFERENCE: FieldNote[] = [
  { key: 'challenges[].challenges[].name', label: 'Activity name', group: 'Challenges', hint: 'Titles this activity in the activity list, below the content, and in the outline on the workshop\'s public page. Blank shows the type instead.', detail: 'It labels the activity row in the activities list (up to two lines) and the heading shown directly beneath the player or content, and it is quoted in the messages that confirm an activity as complete or explain why the next one is not open yet. The same text is listed in the workshop outline on the public workshop page, so people browsing before they enrol can read it. Left blank, the list and the heading fall back to the activity type and an evolution playback falls back to "Your Evolution", but the public outline simply shows an empty line.', unused: false },
  { key: 'challenges[].challenges[].type', label: 'Activity type', group: 'Challenges', hint: 'Decides what the learner actually does here and which fields below you need to fill in. Changing it clears the previous type\'s fields.', detail: 'The app builds a completely different screen per type — a player, a form, a quiz, a recorder, a download — and each type has its own rule for when Next unlocks. A type the app doesn\'t recognise renders a "coming soon" placeholder instead of any content, so an activity left without a type shows nothing useful.', unused: false },
  { key: 'challenges[].challenges[].type=assignment', label: 'Activity type — Assignment', group: 'Challenges', hint: 'The learner submits work here: a linked form, a typed answer, or uploaded files. They can\'t continue past this step until they submit.', detail: 'Choose Form to show a form you have already built, or Question with either a typing box or a file picker, where you can limit which kind of file is accepted. The topic and brief you write here only appear for the two Question styles — a Form activity shows just the form, and if no form is linked the learner sees an "unavailable" message and can never get past this step. Submissions are saved once and shown back read-only, so the learner cannot change an answer after sending it.', unused: false },
  { key: 'challenges[].challenges[].type=audio', label: 'Activity type — Audio', group: 'Challenges', hint: 'The learner listens to an audio track and can only continue once it plays to the end. Any image you add shows only if the track has no cover art of its own.', detail: 'The Next button stays locked — with an on-screen note asking the learner to finish listening — until playback reaches the last few seconds, and it picks up where they left off if they come back. Because the progress bar can be dragged, this gates reaching the end rather than proving they listened to every minute. The image you attach is only a stand-in: the track\'s own cover art is used whenever it has one.', unused: false },
  { key: 'challenges[].challenges[].type=evolutionmapping', label: 'Activity type — Evolution mapping', group: 'Challenges', hint: 'Replays the learner\'s own Before and After video answers, After first, so they can see how far they\'ve come. Both must already be recorded, or they cannot move past this step.', detail: 'The learner gets an After tab and a Before tab, plays each recording, and only unlocks the Next button once both have been watched. The clips come from the two video answers elsewhere in this workshop that are marked as the final Before and After, and they only appear once the learner has actually recorded them — until then the learner sees a "not ready yet" message and is stuck on this step, so place it after both recordings are done. The heading and blurb come from this activity\'s own name and description; leave the name blank and it reads "Your Evolution".', unused: false },
  { key: 'challenges[].challenges[].type=form', label: 'Activity type — Form', group: 'Challenges', hint: 'The learner fills in and submits the form you pick here, and can\'t move on until they submit it. Your activity name and description still show around it.', detail: 'The form opens inside the activity area with a button to expand it full screen, and the answers are saved against this activity. Once submitted the answers lock — reopening only shows what they sent, read-only. If you don\'t pick a form the learner sees an "isn\'t available" message and can never get past this step.', unused: false },
  { key: 'challenges[].challenges[].type=note', label: 'Activity type — Note', group: 'Challenges', hint: 'A short message the learner just reads — nothing to submit. It adds nothing to the progress percentage, but must still be clicked through.', detail: 'Fill in the note\'s heading and its formatted body; the learner sees them centred on the activity screen and can always continue straight away, with nothing to complete. Progress percentages ignore notes entirely, so a set made only of notes never shows progress or turns green. A note must still be clicked through, though: anything placed after it in the set stays locked, and a note left at the end of a set keeps the next set locked even while that set reads 100%.', unused: false },
  { key: 'challenges[].challenges[].type=offer', label: 'Activity type — Offer', group: 'Challenges', hint: 'The learner sees a reward card with a Claim Now button. They must tap it to open your link before Next unlocks — a blank link traps them.', detail: 'The heading, description and link you enter appear on a card with a Claim Now button that opens the link in the browser or another app. Opening it is all that is needed to mark the step done — the app cannot tell whether the learner did anything on the other side. This step cannot be skipped, so if the link is blank or will not open, the learner gets an error and can never reach the rest of the workshop.', unused: false },
  { key: 'challenges[].challenges[].type=quiz', label: 'Activity type — Quiz', group: 'Challenges', hint: 'Learners answer your chosen questions one at a time and see right away whether each was right. Once finished it can\'t be retaken.', detail: 'The learner picks an option and submits; the right choice is then highlighted and an explanation appears — on a wrong answer that explanation is taken from the correct option, so always write one there. Answers are saved as they go, and Next stays locked until the last question is answered. Re-opening a finished quiz shows a read-only review of what was answered, but leaving partway through starts it over from the first question.', unused: false },
  { key: 'challenges[].challenges[].type=resource', label: 'Activity type — Resource', group: 'Challenges', hint: 'The learner downloads the file you upload here, shown under the title you give it. Without a file they can never move past this step.', detail: 'Shows a card with your title, the step\'s description, a "Download your Resource Here" caption and a Download Resources button that opens the file in the learner\'s browser or file manager. Opening it is what unlocks the Next button — the app can only tell that the link was opened, not that the file was read. If no file is attached, the button just reports that nothing is set up and the learner stays locked on this step, and if the title is left blank the card shows no heading.', unused: false },
  { key: 'challenges[].challenges[].type=video', label: 'Activity type — Video', group: 'Challenges', hint: 'The learner watches the episode you pick and can only move on once it plays through to the end. Without an episode they get stuck.', detail: 'Next stays disabled until playback reaches within a few seconds of the end, and until then the learner is told to finish watching to continue; playback, resume and watch-time tracking behave exactly as they do elsewhere in the app. If no episode is chosen the learner just sees an error box and can never get past this step. The thumbnail is only the still shown before playback starts, and only when the chosen episode has no image of its own.', unused: false },
  { key: 'challenges[].challenges[].type=videoask', label: 'Activity type — VideoAsk', group: 'Challenges', hint: 'The learner records a video reply of at least 15 seconds. Choose a VideoAsk template — without one they can\'t record and can\'t move on.', detail: 'They see the prompt — a video, which plays in the same wide player a Video activity uses, or a still image — then swipe to record with their camera or upload a clip up to 100 MB, preview it, and submit. Next stays locked until they submit a reply of at least 15 seconds, and if no template is chosen they only get an error message with no way to record or continue. You can also flag the recording as a Before or an After so it replays in an Evolution mapping activity; only two activities in the whole workshop can carry that flag, one of each.', unused: false },
  { key: 'challenges[].challenges[].type=zoomcall', label: 'Activity type — Zoom call (retired)', group: 'Challenges', hint: 'Learners still see this step, but it only shows a "coming soon" card — set the live call up as its own section instead.', detail: 'The app does not treat a live call as an activity, so instead of a countdown and a join button the learner gets a placeholder card saying it is coming soon. It still takes a numbered slot in their list and counts toward the completion percentage, though it is ticked off as soon as they press Next, so it does not block them. A live call added as its own section works properly — countdown, join button, and the recording afterwards.', unused: true },
  { key: 'challenges[].challenges[].assignmenttype', label: 'Assignment type', group: 'Challenges', hint: 'Choose Form to have the learner fill in a prepared form, or Question to have them write an answer or upload a file.', detail: 'Either way the learner cannot move on until they submit. Form shows the form you attach just below, and Question shows the topic and brief with a typing box or a file picker underneath, depending on the Submission choice. If you pick Form and leave no form attached, learners see a "not available" message and can never get past that step.', unused: false },
  { key: 'challenges[].facilitatoronly', label: 'Audience — Facilitators only', group: 'Challenges', hint: 'Hides this set from every learner, cohort members included, so only named facilitators see it — and only when Category based is on.', detail: 'When on, the set disappears for every enrolled learner, cohort members included, and only people named as facilitators of this workshop still see it. It only takes effect in a workshop with Category based turned on; with that off the app shows the set to everyone, so it is not a safe way to hide facilitator material in a plain workshop. If nobody is named as a facilitator, the set is hidden from absolutely everyone; and with this switch off, visibility still follows the categories chosen for the set.', unused: false },
  { key: 'challenges[].challenges[].finalevolutiontype', label: 'Before / After', group: 'Challenges', hint: 'Picks which clip this recording becomes in the closing evolution replay, where the After clip plays first and Before second.', detail: 'The closing replay gathers every recording flagged for it, plays the After ones first and then the Before ones, and the learner cannot move on until all of them have been watched. The two choices are not exclusive: if two recordings are given the same one, both play, one after the other. A clip only appears if the learner actually submitted that recording — unsubmitted ones are skipped silently, and if none were submitted the learner sees a "not available yet" panel instead of the replay.', unused: false },
  { key: 'challenges[].duedate', label: 'Call starts — date', group: 'Challenges', hint: 'The day of the live call. It drives the big countdown clock, and the Join Call button unlocks 15 minutes before that moment.', detail: 'This date is combined with the call time into a single moment: learners watch days, hours, minutes and seconds tick down to it, then see a LIVE NOW badge once it passes, and Join Call becomes tappable 15 minutes early. Leave the date blank and nothing counts down and Join Call stays permanently disabled — a call time on its own has no effect without a date. Set a date but no time and the countdown runs to midnight at the start of that day, so the call shows as live from first thing in the morning.', unused: false },
  { key: 'challenges[].duetime', label: 'Call starts — time', group: 'Challenges', hint: 'Sets when the live call starts: learners see a countdown to it and the Join button unlocks 15 minutes before. Needs the call date set too.', detail: 'Only the time of day is taken from this value and applied to the call date, so the date shown in this picker is ignored. If no call date is set, the countdown just reads "Call time to be announced" and the Join button stays greyed out with "You can join 15 minutes before the call." Once the call is marked complete, the recording replaces the countdown and this time stops mattering.', unused: false },
  { key: 'challenges[].workshopcategory', label: 'Categories', group: 'Challenges', hint: 'In a focus-group workshop this set is shown only to the groups picked here; left empty, no ordinary participant sees it.', detail: 'In a workshop that asks learners to pick a focus group, an ordinary participant sees only the sets tagged with the group they chose; a set with nothing selected here reaches none of them, even though the summary beside the label reads "All". Facilitators and cohort members skip this filter and see every group\'s sets. In a workshop that does not use focus groups it has no effect at all.', unused: false },
  { key: 'challenges[].completedzoomurl', label: 'Completed Zoom URL', group: 'Challenges', hint: 'Has no effect in the app today — learners always watch the recording picked in the Recording field, never a link pasted here.', detail: 'Only the retired workshop screen ever opened this pasted link; the screen learners use now plays the recording chosen in the Recording field next to it. Be aware it is not a backup: if a call is marked completed with no recording attached, learners just see a message saying the recording will appear soon, and a link typed here will not fill that gap.', unused: true },
  { key: 'challenges[].description', label: 'Description (activity set)', group: 'Challenges', hint: 'Shown when this set is expanded in the Workshop Flow list on the enrollment page; also fills in for any activity inside it that has none.', detail: 'On the enrollment page this text appears under the set\'s title as soon as a visitor expands it in the Workshop Flow list. Inside the player it is only a backup — the app shows the current activity\'s own blurb and drops back to this one when that is empty. The whole set is copied to each learner when they enrol, so player-side edits only reach people who enrol afterwards.', unused: false },
  { key: 'challenges[].challenges[].description', label: 'Description (activity)', group: 'Challenges', hint: 'Shown under the activity title while the learner is on it, trimmed to two lines with a Read more link when longer.', detail: 'It appears beneath the title of whichever activity the learner is on, collapsed to about two lines with a Read more link. If you leave it empty, the section\'s own description is shown in its place. On a downloadable resource and on an evolution playback the same text is also printed inside the activity itself, so it shows twice — keep it short there.', unused: false },
  { key: 'challenges[].challenges[].assignmentdescription', label: 'Description (assignment)', group: 'Challenges', hint: 'Has no effect in the app today — the brief learners read comes from Rich description below. If that is blank, learners get no brief.', detail: 'The current workshop screen shows an assignment as its topic heading followed by the rich brief only, so whatever you type here is saved but never reaches a learner. Fill in Rich description instead — if it is left empty the learner sees the heading and the submission box with no instructions at all. The retired workshop screen did display this plain line, but that screen is no longer reachable from anywhere in the app.', unused: true },
  { key: 'challenges[].challenges[].evolutionmappingdescription', label: 'Description (evolution mapping)', group: 'Challenges', hint: 'Has no effect in the app today — the playback screen uses the activity description above instead.', detail: 'The blurb under the evolution playback heading comes from the activity\'s own description. Nothing typed here reaches the learner.', unused: true },
  { key: 'challenges[].description@zoomcall', label: 'Description (live call)', group: 'Challenges', hint: 'The blurb about the call — shown on its card in the list and again in the call view, before the call and under the recording afterwards.', detail: 'A live call always uses this text: there is no activity beneath it to supply its own, so it cannot be overridden the way a step with activities can. It shows on the call\'s row in the activity list, inside the call view (under the countdown before the call, under the replay once the call is done), and once more as the "Read more" line below the player — so keep it short, and avoid wording that only makes sense before the call. It also appears in the Workshop Flow section on the enrollment page once that step is tapped open.', unused: false },
  { key: 'challenges[].challenges[].contentref@video', label: 'Episode', group: 'Challenges', hint: 'The video the learner watches here. Without one they see an error and can never finish it, so the rest of the workshop stays locked.', detail: 'Point it at an item in the episode library; playback and watch-time tracking behave exactly as they do everywhere else in the app. The learner has to watch to within a few seconds of the end before Next turns on — until then they are prompted to finish watching the video to continue. Leaving it empty is a hard block, not a cosmetic one: the step can never be completed, so Next never turns on and every activity after it stays locked.', unused: false },
  { key: 'challenges[].challenges[].finalbeforeafter', label: 'Final before / after', group: 'Challenges', hint: 'Has no effect in the app today. The playback already shows both clips whenever a Before and an After recording are flagged.', detail: 'Only the older workshop screen read this switch. The current app simply collects whichever recordings are flagged, so leaving it off changes nothing for the learner.', unused: true },
  { key: 'challenges[].challenges[].finalevolution', label: 'Final evolution mapping', group: 'Challenges', hint: 'Marks this video ask recording to be replayed later in the learner\'s Your Evolution activity. Flagging any other kind of step does nothing.', detail: 'The Your Evolution activity gathers every flagged video ask across the whole workshop and replays them — the After clip first, then Before, using the slot setting beside this one. Nothing changes about this step itself for the learner, and there is no enforced limit of two: any extra flagged recording just adds another clip to the reel, while a flag on a step that is not a video ask is ignored entirely. Clips only appear once the learner has actually recorded them, so if none have been submitted the learner is simply told their evolution videos aren\'t ready yet.', unused: false },
  { key: 'challenges[].challenges[].contentref@form', label: 'Form', group: 'Challenges', hint: 'The form the learner fills in and submits. Without one they\'re stuck: nothing to submit, so they can never move past this step.', detail: 'It opens inside the workshop stage with a button to expand it full screen, and the form brings its own title, intro text and questions, so there is no need to repeat them here. Next stays greyed out until the learner submits, prompting them to submit the form to continue, and their answers lock read-only once sent. If no form is chosen they are told it isn\'t available and are blocked at this step permanently, so never leave it empty.', unused: false },
  { key: 'challenges[].heading', label: 'Heading', group: 'Challenges', hint: 'The set\'s main title — the bold line on its card in the learner\'s list, and the small context line above whatever they are working on.', detail: 'It titles the set on the learner\'s activity list, sits as muted context above whatever activity is open, and heads the set in the Workshop Flow list on the page people see before they enrol. Left blank it falls back to "Challenge" (or "Live Call" / "Zoom call") in the activity list and the progress timeline, but not in that pre-enrolment flow list, where a blank title leaves a stray colon in front of the subtitle. For a live call this same text is also the large title on the call screen itself.', unused: false },
  { key: 'challenges[].hidezoom', label: 'Hide call', group: 'Challenges', hint: 'Hides this live call inside the workshop — it drops out of the learner\'s activity list and Previous/Next skip over it.', detail: 'Use it to park a call you are not ready to run: hidden calls disappear from the activity list, from the Previous/Next sequence and from the end-of-workshop recap, so nobody can open or join them. One catch — it is only hidden inside the workshop. The call still shows in the Workshop Flow list on the enrollment page people read before they join.', unused: false },
  { key: 'challenges[].headicon', label: 'Icon', group: 'Challenges', hint: 'The small badge image on the left of this set\'s card. Without one, a generic flag icon is shown instead.', detail: 'Displayed in a fixed 40x40 slot and fitted whole rather than cropped, so logos and badges are never cut off. While the set is still locked the icon is dimmed and a padlock is drawn over it.', unused: false },
  { key: 'challenges[].startlivecall', label: 'Live call starts text', group: 'Challenges', hint: 'The small caption above the countdown clock, shown in capitals. Leave it blank and it reads "Live call starts in".', detail: 'Purely a label — it changes no timing. If no call date is set, this text is shown on its own where the countdown would be, defaulting to "Call time to be announced".', unused: false },
  { key: 'challenges[].challenges[].meetdate', label: 'Meet date (retired activity)', group: 'Challenges', hint: 'Has no effect in the app today. It belongs to a retired activity type — to schedule a live call, use a set whose type is Zoom call.', detail: 'An activity of this old type is not built any more: the learner sees a "coming soon" placeholder step with no date, countdown or join button, and can simply move past it. A live call learners actually join is set up on a whole set switched to the Zoom call type, which shows the countdown and enables the join button shortly before the call starts.', unused: true },
  { key: 'challenges[].challenges[].notedescriptionrich', label: 'Note (rich)', group: 'Challenges', hint: 'The formatted note body the learner reads. Fill this or the plain Note description — not both; this one wins.', detail: 'Shown with your formatting, centred beneath the Note head, and it replaces the Note description whenever both are filled. On the older workshop screen, still reachable by a direct link, the two are shown one under the other instead, so filling both can display the text twice. Notes are deliberately left out of the set\'s progress bar and the overall workshop percentage, so adding them never makes a learner\'s progress look smaller.', unused: false },
  { key: 'challenges[].challenges[].notedescription', label: 'Note description', group: 'Challenges', hint: 'Unformatted note text shown under the note heading; the current player uses it only when the rich note below is empty.', detail: 'On the note screen the learner sees the heading and then one body: the rich note if it has any content at all, otherwise this plain line, centred and without formatting or links. The older workshop screen, still reachable from a home banner, stacks both instead of choosing one, so filling in both can show the same text twice. Notes never gate progress — the learner can always continue, and notes are left out of the progress count.', unused: false },
  { key: 'challenges[].challenges[].notehead', label: 'Note head', group: 'Challenges', hint: 'The bold pink headline centred at the top of a note. The note\'s own title already shows just below it, so avoid repeating the same words.', detail: 'Optional — leave it empty and the note opens straight into its body text. It always prints in the same brand pink used for headings and buttons throughout the app, and it stands in as the note\'s title on the end-of-workshop summary when the note has no title of its own. Notes are informational only, so this never affects a learner\'s progress.', unused: false },
  { key: 'challenges[].challenges[].quizref', label: 'Quizzes', group: 'Challenges', hint: 'The questions the learner answers here. With none picked they see "This quiz isn\'t available." and cannot move past this step.', detail: 'Questions are asked one at a time; after each answer the app shows whether it was right, with the explanation written on that option. Answers save as they go and Next only unlocks once the last question is answered, so a quiz left with no questions leaves the learner stuck on that step. Re-opening a finished quiz shows their answers and score read-only instead of restarting it.', unused: false },
  { key: 'challenges[].zoomvideoref', label: 'Recording', group: 'Challenges', hint: 'The recorded call learners watch once this call is marked Completed. Only people who enroll after you save will see it.', detail: 'Pick a video from the library and it plays inline in place of the countdown, exactly like a video lesson. If the call is marked Completed but nothing is attached yet, learners see "This call has ended. The recording will appear here soon." Each learner keeps the copy of the curriculum made when they enrolled, so a recording added afterwards reaches only people who enroll after you save — the group that attended the live call will not see it, which makes this most useful on replay and evergreen workshops.', unused: false },
  { key: 'challenges[].challenges[].uploadedresourcetitle', label: 'Resource title', group: 'Challenges', hint: 'The heading on the download card. Leave it blank and the card opens straight into the description.', detail: 'Sits above the activity\'s description, the "Download your Resource Here" caption and the download button.', unused: false },
  { key: 'challenges[].challenges[].uploadedresource', label: 'Resource URL', group: 'Challenges', hint: 'The file the download button hands the learner. If it is empty they only see an error and cannot move past this step.', detail: 'Filled in for you by the upload. The file opens in their browser or file manager, and simply opening it is what unlocks Next — the app cannot tell whether they actually kept or read it. Because Next stays locked until they open it, leaving this empty strands the learner on this step.', unused: false },
  { key: 'challenges[].challenges[].rewarddescription', label: 'Reward description', group: 'Challenges', hint: 'The body text under the offer heading, explaining what the learner is about to claim.', detail: 'Shown as plain text between the heading and the Claim Now button. Formatting is not supported here.', unused: false },
  { key: 'challenges[].challenges[].rewardhead', label: 'Reward head', group: 'Challenges', hint: 'The heading on the offer card, above the description and the Claim Now button. It also titles this step in the end-of-workshop recap when the step has no name.', detail: 'Leave it blank and the card simply starts with the description; the Claim Now button and its link are unaffected. The same text is reused as this step\'s title in the recap the participant sees after finishing the workshop, but only when the step\'s own name is empty — with both blank that line falls back to just "Reward".', unused: false },
  { key: 'challenges[].challenges[].rewardlink', label: 'Reward link', group: 'Challenges', hint: 'Where Claim Now sends the learner. Without it they can\'t move past this step — the button just says no link is set up.', detail: 'Opens outside the app, in the learner\'s browser. Opening it is what marks the step done and unlocks Next — the app never checks whether they actually claimed anything on the other side. Paste a complete web address: if the link is missing or won\'t open, the learner sees an error and stays stuck on this step.', unused: false },
  { key: 'challenges[].challenges[].assignmentdescriptionrich', label: 'Rich description', group: 'Challenges', hint: 'The formatted brief the learner reads before answering. It appears only on Question-style assignments, not Form ones.', detail: 'Rendered with your formatting under the topic heading and above the answer box or file picker, for both the typed-answer and the file-upload submission styles. If the assignment is set to use a form instead, the app loads that form and this brief is never shown to the learner — put the instructions inside the form itself.', unused: false },
  { key: 'challenges[].type', label: 'Set type', group: 'Challenges', hint: 'Choose whether this set holds activities the learner works through, or is a scheduled live call with a countdown and a Join button. A live call never unlocks the next set on its own.', detail: 'An activity set appears to the learner as an expandable card with a progress bar and its activities listed inside. A live call appears instead as a single card marked as a live call; opening it shows a countdown to the scheduled time and a Join button that only becomes clickable 15 minutes before the call, and once the call is marked completed that is replaced by the recording. Live calls are left out of the workshop progress figure and never unlock the next set — the next set still waits for the last activity set to be fully finished — so a live call cannot be used to gate the journey.', unused: false },
  { key: 'challenges[].challenges[].contentref@audio', label: 'Solar Voice', group: 'Challenges', hint: 'The audio the learner listens to at this step. If it is left empty they hit an error and can never move past this step.', detail: 'Picked from the Solar Voice library and played in the workshop\'s audio player, which resumes where the learner left off and logs their listening time. The step only completes once playback runs to the end — until then the learner is told to finish listening before they can continue. With nothing selected the player shows an error instead, so the step can never be completed and every activity after it stays locked.', unused: false },
  { key: 'challenges[].status', label: 'Status — Completed', group: 'Challenges', hint: 'Turn this on after the call has taken place — the countdown and Join Call are replaced by the recording, and Next unlocks on that call. It does not change anything for learners who enrolled before you switched it on.', detail: 'While it is off the learner sees a live countdown plus a Join Call button (active from 15 minutes before the scheduled time) and Next stays disabled on that call, reading "You can continue once this live call is completed." Switching it on removes the countdown and the join link for good and shows the uploaded recording instead — or "This call has ended. The recording will appear here soon." until one is attached — so switch it on only once the call is over. Two limits worth knowing: each learner works from the copy of the plan made when they enrolled, so switching this on later does not reach people who are already enrolled; and the call neither locks nor unlocks the set that follows it, which still depends on the previous activity set being finished.', unused: false },
  { key: 'challenges[].subheading', label: 'Sub heading', group: 'Challenges', hint: 'A short second line under the heading on this set\'s card. Leave it blank and nothing is shown.', detail: 'Appears directly under the heading on the set card, and under the title on a live call (in cyan). It also shows in the Workshop Flow preview on the enrollment page.', unused: false },
  { key: 'challenges[].challenges[].submissionformat', label: 'Submission', group: 'Challenges', hint: 'Choose Text to give the learner a typing box, or Upload to give them a file picker. Left unset, they get the typing box.', detail: 'Text shows a multi-line answer box with a Submit button that stays disabled until they type something, then shows their answer back read-only. Upload lets them attach several files at once, limited to the upload type you pick alongside it, and afterwards lists each file as a link they can reopen. Pick one explicitly: if neither is selected the current app quietly falls back to the typing box, and the older workshop screen shows the assignment with no answer area at all.', unused: false },
  { key: 'challenges[].challenges[].thumbnail', label: 'Thumbnail', group: 'Challenges', hint: 'Cover art for the activity: the poster before a video plays, and the artwork on the audio card. Only used when the chosen content has none.', detail: 'For a video activity it is the still frame held over the player until the learner presses play; for audio it is the square artwork on the player card. The episode or audio you select supplies its own image first, so this one appears only when that image is missing. With neither, the video stage stays plain black and the audio card shows a generic placeholder.', unused: false },
  { key: 'challenges[].challenges[].evolutionmappingtitle', label: 'Title (evolution mapping)', group: 'Challenges', hint: 'Has no effect in the app today — the playback screen uses the activity name above instead.', detail: 'The evolution playback takes its heading from the activity name, falling back to "Your Evolution" when that is blank. Nothing typed here reaches the learner.', unused: true },
  { key: 'challenges[].challenges[].assignmenttopic', label: 'Topic', group: 'Challenges', hint: 'The bold heading at the top of the assignment card, above the brief. Leave it blank and the card starts with the brief instead.', detail: 'It appears the same way whether the learner types an answer or uploads files. It also stands in as the activity\'s title in the end-of-workshop summary when the activity has no name of its own, so leaving both blank shows only a generic "Assignment" label there.', unused: false },
  { key: 'challenges[].startdate', label: 'Unlocks on — date', group: 'Challenges', hint: 'The day this set unlocks; before it the learner sees a greyed-out, locked card. Changing it later won\'t move learners already enrolled.', detail: 'Two gates must both pass before the set opens: this date, at the time set beside it, and the previous activity set being fully completed — live calls are skipped when working out "the previous set", so a call marked completed never opens the next set by itself. Left empty, the set opens as soon as the one before it is finished; if the date has already passed but earlier work is still outstanding, the card reads "Complete the previous challenge to unlock" rather than showing a misleading past date. Each learner is handed their own copy of this schedule the moment they enrol, so edits here reach new enrolments only — people already in the workshop keep the dates they started with.', unused: false },
  { key: 'challenges[].starttime', label: 'Unlocks on — time', group: 'Challenges', hint: 'The time of day the unlock date takes effect. It does nothing on its own unless an unlock date is also set.', detail: 'Only the clock time is taken from here and pinned onto the unlock date to form the exact unlock moment; the date part of the picked time is ignored. Passing that moment lifts the date lock only — the set can still stay locked while an earlier set is unfinished. Learners see the full unlock moment, year included, in the lock message on the card.', unused: false },
  { key: 'challenges[].challenges[].uploadtype', label: 'Upload type', group: 'Challenges', hint: 'Limits what a learner may attach — PDF, Word document, image, video, audio, or anything. Only applies to upload assignments.', detail: 'The chosen kind filters the learner\'s file picker and is named on the button, for example "Pick pdf file(s)". Beware that the document option accepts Word files only (.doc and .docx) — a learner with a PDF is blocked, so pick PDF or anything when formats may vary. Leaving it unset behaves like anything: any file is accepted and the button simply reads "Pick files".', unused: false },
  { key: 'challenges[].challenges[].contentref@videoask', label: 'VideoAsk template', group: 'Challenges', hint: 'The prompt the learner answers by recording themselves — a video or a still image. Without one, the activity can\'t load.', detail: 'The template supplies only the prompt the learner sees: a video that plays in the normal player, or a still image. Any wording stored on the template itself is never shown, so the instructions the learner reads must go in this activity\'s own title and description. The learner swipes to record with their camera or uploads a clip (rejected above 100 MB), previews it and submits; Submit stays disabled under 15 seconds, and Next stays locked until a response is submitted.', unused: false },
  { key: 'challenges[].zoomlink', label: 'Zoom link', group: 'Challenges', hint: 'The meeting link the Join Call button opens. Without it, tapping join tells the learner the link isn\'t available yet.', detail: 'Opens outside the app in the learner\'s browser or Zoom app, and only becomes tappable 15 minutes before the scheduled call time. If the call has no date set the button stays greyed out permanently, so always give the call a date and time as well as a link. Once the call is marked complete the link is no longer used — the recording plays in its place.', unused: false },
  { key: 'challenges[].challenges[].zoomlinkchallenge', label: 'Zoom link (retired activity)', group: 'Challenges', hint: 'Has no effect in the app today — this is a retired activity type. To schedule a live call, make the whole set a Zoom call set instead.', detail: 'The app does not recognise this old activity type, so this link is never used and the learner sees a "coming soon" placeholder where the call details would be. The step still appears in the learner\'s sequence and counts toward that set\'s activity total and completion percentage, so remove the activity rather than leaving it in place. Live calls are set up by making the whole set a Zoom call.', unused: true },
  { key: 'bonusfooter', label: 'Bonus closing line', group: 'Enrollment page', hint: 'Was the centred closing line under the divider at the foot of the old screen\'s bonus panel. It has no effect on the current workshop page.', detail: 'On the retired workshop screen this closed the bonus panel, centred beneath a thin divider, and appeared only when the bonus panel was switched on. The current workshop page has no bonus panel, so it never reaches a learner.', unused: true },
  { key: 'bonushead', label: 'Bonus headline', group: 'Enrollment page', hint: 'The bold headline above the struck-through price in the bonus panel. It only shows on the older workshop page, not the current one.', detail: 'In the bonus panel this is the big bold line sitting directly above the struck-through price and the price — right-aligned beside the bonus text on wide screens, centred below it on phones. It renders only on the older workshop page, which the app no longer links to but which still opens from old saved links; the current workshop page ignores it entirely. If the bonus panel is switched on, keep this filled in — clearing it breaks that panel.', unused: true },
  { key: 'bonussection', label: 'Bonus intro line', group: 'Enrollment page', hint: 'Was the underlined opening line of the old screen\'s bonus panel. It has no effect on the current workshop page.', detail: 'On the retired workshop screen this sat at the top of the bonus panel as a short underlined lead-in above the two body lines, and only when the bonus panel was switched on. The current workshop page has no bonus panel, so this text is never shown.', unused: true },
  { key: 'bonus1', label: 'Bonus line 1', group: 'Enrollment page', hint: 'Was the first body line of the old screen\'s bonus panel. It has no effect on the current workshop page.', detail: 'On the retired workshop screen this was the first of two paragraphs under the panel\'s opening line, shown only when the bonus panel was switched on. The current workshop page has no bonus panel, so it is never displayed.', unused: true },
  { key: 'bonus2', label: 'Bonus line 2', group: 'Enrollment page', hint: 'Second line of the bonus panel\'s text, under the first. Shows only on the older workshop page, and only when that panel is switched on.', detail: 'On the older workshop page — still live and reachable from the legacy workshop list — this is the second paragraph of the bonus panel, directly under the first, in the column beside the struck-through and current price. It appears only when the bonus panel is switched on. The redesigned workshop page does not read it at all, so it never shows there; leave it filled in rather than blank, since the older page expects text here whenever the panel is on.', unused: true },
  { key: 'day', label: 'Duration / format line', group: 'Enrollment page', hint: 'Short highlighted line just above the price at the bottom of the workshop page, e.g. "3 Days" — display only, it sets no dates.', detail: 'Printed exactly as typed at the very bottom of the workshop page, bold and in the accent colour, the same size as the price directly beneath it. It is display text only — nothing else in the app reads it, so it does not set the start date, the length of the workshop, or when it completes. If it and both price lines are all left empty the whole bottom block is hidden; the older workshop screen shows the same line centred inside the Workshop Overview box.', unused: false },
  { key: 'enrollbuttonname', label: 'Enrollment button text', group: 'Enrollment page', hint: 'The wording on the main enrollment button, shown under the intro and again at the end of the page. Leave it blank for "ENROLL NOW".', detail: 'It labels the plain enrollment button only. Where the person is shown a price or asked for a code to redeem, that button is replaced by a pricing card with its own "Enroll Now" wording, and someone waiting their turn on an evergreen workshop sees a fixed START button instead - this text is ignored in both cases. The blank fallback applies to the current workshop page; the retired one shows whatever is stored, including nothing at all.', unused: false },
  { key: 'amount', label: 'Fallback buy-card price', group: 'Enrollment page', hint: 'A price label only: it fills in on the buy card when the payment settings have no price, and never changes what a learner is charged.', detail: 'It only ever appears on the inline buy / coupon card, which shows solely on evergreen workshops offering a paid or referral-coupon route, and never to a learner who already has free access. It is display text: the charge is calculated on the server from the payment settings, so a number here can never change what a learner pays. Because the discount is worked out from the payment settings alone, a price coming from here appears bare — no crossed-out original price and no percentage-off badge.', unused: false },
  { key: 'faq', label: 'FAQ', group: 'Enrollment page', hint: 'Each question appears as a numbered card near the bottom of the enrollment page, opening to show its answer when tapped.', detail: 'Questions are numbered automatically (01, 02, …) in the order you list them, all start closed, and the whole section disappears when there are none. It sits near the end of the page, after the "Who Is This Workshop For?" copy when that is filled in, and just above the workshop overview box. Answers show as plain text only — bold, bullets and clickable links are not supported, so a web address will appear as unclickable text.', unused: false },
  { key: 'hometags', label: 'Hometags', group: 'Enrollment page', hint: 'Small uppercase chips laid over the top of the workshop\'s picture on its home-screen card.', detail: 'Each entry becomes an uppercase chip pinned over the top-left of the card image, wrapping to a second line when there are several. They appear only in the home screen\'s premium programs row and its View all grid — never on the workshop page itself — and only when the workshop is set to run as evergreen and is flagged to show on the home screen.', unused: false },
  { key: 'joinus', label: 'Join us section', group: 'Enrollment page', hint: 'Fills the "Who Is This Workshop For?" section on the enrollment page. Leave it empty and the whole section, heading included, disappears.', detail: 'Rendered as formatted copy under the "Who Is This Workshop For?" heading, sitting between the commitments list and the questions. Bold, colour and highlight formatting all survive, but links inside it never open. Only people who have not enrolled yet ever see it — once someone is enrolled the app takes them straight to their own workshop screen.', unused: false },
  { key: 'knowinfo', label: 'Know info', group: 'Enrollment page', hint: 'Appears on the workshop page under a "Your Commitments" heading — each item is a small icon beside one short line of text.', detail: 'The rows sit between the "An Exclusive Glimpse" panel and the "Who Is This Workshop For?" copy, laid out as plain lines with no card or border around them. An item whose icon is missing or fails to load shows a cyan lightning bolt instead, and the text is shown exactly as typed — bold, links and other formatting are ignored here. Leave the list empty and the whole section, heading included, disappears from the page.', unused: false },
  { key: 'pricestriked', label: 'Original price (crossed out)', group: 'Enrollment page', hint: 'The old, higher price, shown crossed out next to the price in the line at the foot of the workshop page, above the enrol button.', detail: 'Decorative only — nothing is calculated from it and it is never used at checkout. It is a separate line near the bottom of the page from the buy card\'s own price and crossed-out original, which come from the payment settings, so keep the two in step or the page will show two different prices. It also appears on its own if the price next to it is left empty, so fill both or neither.', unused: false },
  { key: 'outcome', label: 'Outcomes', group: 'Enrollment page', hint: 'The row of highlight stats on the workshop\'s home-screen card — a big figure with a short caption under it. Keep it to about three.', detail: 'Entries render side by side as glossy tinted boxes just under the card\'s summary line, with the figure in the card\'s accent colour above its caption. They share a single row and never wrap, so a fourth or fifth entry squeezes the rest. An entry with neither a figure nor a caption is dropped. Like the rest of the card, this only shows for evergreen workshops flagged to appear on the home screen.', unused: false },
  { key: 'workshopoverview', label: 'Overview', group: 'Enrollment page', hint: 'The highlighted "Workshop Overview" box at the very end of the page — one picture-and-text line per item.', detail: 'It is the last section before the day and price footer, rendered inside the page\'s gradient-bordered box, after the questions. Each item\'s picture sits to the left of its line of text, and an item with no picture shows a cyan lightning icon. Text is shown exactly as typed with no formatting, and the box is hidden when nothing is listed.', unused: false },
  { key: 'dynamicenrollment', label: 'Page blocks', group: 'Enrollment page', hint: 'Extra sections you write yourself, shown in the order you arrange them, part-way down the sign-up page after the Workshop Flow steps. People who have already enrolled never see that page.', detail: 'A Rich text block shows a heading followed by fully formatted body copy; an Icon text block shows a heading followed by rows of a small picture beside its own text. The two title boxes are always merged into a single big heading line, the first part white and the second brand pink, so bold, heading sizes, lists and links typed into them are dropped, while formatting in the body is kept — though links anywhere on this page are not clickable. Full border wraps only the body in the page\'s glowing gradient box and leaves the heading above it, and a block of a type the app does not recognise is skipped without any warning.', unused: false },
  { key: 'type', label: 'Page type', group: 'Enrollment page', hint: 'Has no effect in the app today — whichever option you pick, nothing on the learner\'s workshop page or cards changes.', detail: 'Your choice here is saved with the workshop, but nothing in the learner-facing app reads it: the enrollment page, the workshop cards, the home banners and the screens inside a workshop all ignore it. Both options behave identically today, and older workshops may have been saved with this left blank, so it is safe to leave exactly as it is.', unused: true },
  { key: 'price', label: 'Price', group: 'Enrollment page', hint: 'Shows as a price line near the bottom of the workshop page, printed exactly as typed. It is a label only and never sets what anyone pays.', detail: 'It prints near the bottom of the workshop page beside the crossed-out price, and again on the older workshop and enrollment screens, exactly as you type it — so include the currency symbol yourself. Nothing is calculated from it: the amount actually charged, and the price on the enrol card and the home page cards, all come from the payment settings instead, so this line can drift out of step with them. It also keeps showing to people who have already enrolled, unlike the price on the cards.', unused: false },
  { key: 'registrationEndDate', label: 'Registration closes', group: 'Enrollment page', hint: 'After this date and time the workshop still shows, but enrolling is refused with a "Registration Closed" notice. Paid checkout is not stopped by it.', detail: 'Together with the registration opening date this is the only pair of dates that closes sign-ups, matched to the exact time of day, and it is skipped for evergreen workshops. It applies when someone enrolls for free or redeems a coupon code, but a card purchase is settled by the payment service and is not checked against it, so a paid workshop keeps selling after this time. Leaving it blank means no closing time on the current workshop page, though the retired page still reachable in the app refuses to enroll anyone in a non-evergreen workshop that has any of its dates left blank.', unused: false },
  { key: 'registrationStartDate', label: 'Registration opens', group: 'Enrollment page', hint: 'Learners cannot enroll before this date and time — tapping to enroll just tells them registration is not open yet.', detail: 'This is one of the two dates that genuinely gate enrollment, compared down to the exact time; the workshop and its enroll button stay fully visible beforehand, and the learner is only stopped when they tap. Evergreen workshops ignore it entirely and can be started at any time. On any non-evergreen workshop, fill it in rather than leaving it blank: an older workshop screen still reachable in the app refuses enrollment with a setup error unless both registration dates and both workshop dates are set.', unused: false },
  { key: 'prerequisites', label: 'Requirements', group: 'Enrollment page', hint: 'Nothing in the app reads this today, so requirements entered here are never shown to a learner.', detail: 'Nothing in the app reads this — the workshop page is assembled from a fixed list of content pieces and this one is not on it, in either the current or the legacy screen, so anything typed here is saved but never rendered. If a requirement has to reach learners, put it in Know Info (which appears on the workshop page under the heading "Your Commitments") or in the Description. Both of those do render.', unused: true },
  { key: 'selectedTestimonials', label: 'Selected testimonials', group: 'Enrollment page', hint: 'Attaches participant video testimonials to this workshop, but the current workshop page never shows them — only the retired older page did.', detail: 'Your picks are saved with the workshop and appear as a scrollable row of testimonial videos under an "Experience Shared" heading — but only on the older workshop page, which the app\'s Workshop tab no longer opens, though its original direct link still works. The workshop pages learners reach today show no testimonials at all. Even on the old page, a pick whose recording has no playable video is skipped, and a selection with none of them playable shows an empty "no videos" message.', unused: false },
  { key: 'shortdescription', label: 'Short description', group: 'Enrollment page', hint: 'Shown as a single line under the workshop name on the enrollment page and as the small subtitle on workshop cards.', detail: 'It appears directly beneath the name on the enrollment page in the accent colour, and as the small subtitle under the name on workshop list cards. On the list card it is trimmed to one line, so put the meaningful words first; the home page programme card, which only appears for workshops featured on the home page, shows the full text and wraps it. Leave it blank and nothing is shown in its place.', unused: false },
  { key: 'enablebonus', label: 'Show bonus section', group: 'Enrollment page', hint: 'Adds a coloured bonus panel to the older workshop page, which is still live at its own link. Today\'s workshop page ignores it.', detail: 'On the older workshop page this switch adds a purple-to-blue panel at the end of the enrolment content, showing the underlined intro line, the two bonus lines, a large headline beside the crossed-out and current prices, and a centred closing line. The workshop page learners normally land on has no bonus panel, so for most visitors this changes nothing — but that older page is still reachable at its own address and still obeys this switch. Only turn it on once every bonus text line has content: the older page fails to load if any of them is left empty.', unused: true },
  { key: 'primarylyTaught', label: 'Skills taught', group: 'Enrollment page', hint: 'The app never reads these, so the skills you list here are not shown to learners anywhere.', detail: 'No screen, card, list or filter in the app reads these — they are saved on the workshop record and nothing ever displays them. To make the skills visible, add them to the Workshop Overview rows or to the description on the workshop page; the bullet points on the home-screen card are another option, but that card only appears for evergreen workshops that are set to show on the home screen.', unused: true },
  { key: 'sneakpeak', label: 'Sneak peak', group: 'Enrollment page', hint: 'Adds the "An Exclusive Glimpse" section — each item shows a small picture next to its line of copy, grouped in one highlighted card.', detail: 'The items appear in one gradient-bordered card under the "An Exclusive Glimpse" heading, after your custom page blocks and before the commitments list. Each picture is shown small at a fixed size beside its copy, which wraps over as many lines as it needs and appears exactly as typed — bold, links and other formatting have no effect. An item left without a picture falls back to a generic sparkle icon, a picture link that fails to load shows a small placeholder icon instead, and the whole section is hidden when no items are added.', unused: false },
  { key: 'selectedTaxonomies', label: 'Taxonomies', group: 'Enrollment page', hint: 'Nothing in the app reads this today — the categories picked here do not affect where the workshop appears or how it is found.', detail: 'No screen, row or listing in the app reads this selection. Where a workshop shows up is decided by whether it runs as evergreen, whether it is flagged for the home screen, and the workshop list\'s own visibility rules — not by these categories. Saving it is harmless but produces no visible result.', unused: true },
  { key: 'testimonialmap', label: 'Testimonials', group: 'Enrollment page', hint: 'Has no effect on the current workshop page — testimonial videos only ever appeared on the old workshop screen the app no longer links to.', detail: 'On the retired workshop screen these showed as a horizontally scrolling row of video thumbnails under an "Experience Shared" heading, and any testimonial without a video was skipped. The current workshop page has no testimonials section at all, so nothing chosen here is visible to a learner today.', unused: false },
  { key: 'thumbnailImage', label: 'Thumbnail image', group: 'Enrollment page', hint: 'The wide image near the top of the enrollment page and the background of every workshop card. Without it the Title video has no play button.', detail: 'Shown as a wide 16:9 banner under the heading on the enrollment page, and as the picture behind the name on the workshops list card. When it is empty the enrollment page shows no banner at all — and because the play control sits on top of that banner, a Title video can never be played. Cards with no image fall back to a plain placeholder icon.', unused: false },
  { key: 'titleVideo', label: 'Title video', group: 'Enrollment page', hint: 'Adds a play button over the thumbnail image so people can watch a preview before enrolling; it only appears if a thumbnail image is set.', detail: 'When a video is set here, a play button appears in the middle of the thumbnail image on the enrollment page and opens the clip in the app\'s video player. The button is drawn on top of that image, so if no thumbnail image is set the whole block is hidden and the video is unreachable. Visitors who are not signed in get the sign-in prompt instead of playback, and it does not start playing on its own once they sign in.', unused: false },
  { key: 'learnings', label: 'What you\'ll learn', group: 'Enrollment page', hint: 'Has no effect on the workshop pages learners use today — it only fed a completion panel on the retired workshop screen.', detail: 'The only code that still reads this list builds a "Targeted Outcomes" panel on the retired workshop screen, and even there it appears only in a wide desktop window and only after the participant has finished every activity. Nothing in the app\'s menus or links opens that screen any more — the workshop tab and shared workshop links go to the current workshop page, which never reads this list. Put anything you want learners to actually see in the workshop overview rows or the description.', unused: false },
  { key: 'workshopfor', label: 'Who is this workshop for?', group: 'Enrollment page', hint: 'Becomes the bullet list on this workshop\'s card on the home screen. It does not fill the "Who is this for" section on the workshop page.', detail: 'Each item you add becomes one bullet with a small coloured dot on this workshop\'s card in the premium programs row on the home screen, and on that row\'s View all grid — blank items are skipped, and line breaks typed inside one item do not create extra bullets. That card only appears when the workshop is set to run as evergreen, is switched on for the web app (or in test mode), is flagged to show on the home screen, and is not marked completed. Despite the matching wording, the "Who is this workshop for?" section on the workshop page itself is written in the Join us rich-text block, not here.', unused: false },
  { key: 'whyworkshop', label: 'Why this workshop?', group: 'Enrollment page', hint: 'A short highlighted line between the preview image and the description, used to say why the workshop is worth doing.', detail: 'It appears on the enrollment page only, in the accent colour, immediately above the main description. It is hidden completely when left blank, and it never shows on cards or anywhere inside the workshop once someone has enrolled.', unused: false },
  { key: 'description', label: 'Workshop description', group: 'Enrollment page', hint: 'The main block of copy on the enrollment page, below the hero image and above the first Enroll button. Links in it are not clickable.', detail: 'It sits in the hero block of the enrollment page — under the title, the one-line descriptor, the hero image and the small cyan line — and above the first Enroll button. Headings, bold and highlights are kept, but every link is inert: tapping one does nothing. Any text or highlight colour set in the editor is carried through exactly and overrides the app\'s own styling, and readers can flip the page between light and dark, so copy pasted in with a fixed black or white colour can end up unreadable in one of the two modes; leave it empty and that block is simply skipped.', unused: false },
  { key: 'workshopEndDate', label: 'Workshop end date', group: 'Enrollment page', hint: 'Only the older workshop screens use it — for the date range and day count, and to mark the workshop finished once it passes. The current pages ignore it.', detail: 'On the older screens it pairs with the start date to produce the workshop\'s date range on the card and its total day count, and once it passes a non-evergreen workshop is treated as finished — participants land on the wrap-up view even if their challenges are unfinished. Enrollment on those screens is also refused as an invalid setup unless all four dates are filled in, but that check is skipped entirely for evergreen workshops. The current workshop pages read neither this date nor the start date, and the registration window is driven only by the registration dates.', unused: false },
  { key: 'workshopStartDate', label: 'Workshop start date', group: 'Enrollment page', hint: 'Orders this workshop among the featured programmes on the home screen, newest first. Enrollment is controlled by the registration dates.', detail: 'Its only job in the current app is the running order of the featured programmes strip on the home screen — newest first, and only among the evergreen workshops flagged to appear there; one with no date sorts to the bottom rather than disappearing. The workshop page itself neither shows nor checks it: the registration opening and closing dates alone decide whether someone can enroll. The legacy workshop pages, still reachable by their old link, do use it — for the date range printed on the workshop card, for the days-completed count, and to refuse enrollment with an "Invalid Setup" message when a non-evergreen workshop is missing any of the four dates.', unused: false },
  { key: 'title', label: 'Workshop title', group: 'Enrollment page', hint: 'The big heading on the enrollment page and the name on every card. Blank, it drops off the home page row and shows as “Workshop” elsewhere.', detail: 'This is the heading learners land on when they open the workshop, the name on the workshops list card, the name in the top bar once they are inside, and the name shown on the payment checkout. Leaving it empty does not hide the workshop: it disappears from the featured workshops row on the home page, but the list card and the checkout simply read “Workshop”, and if the workshop is set to run as a home banner it still appears there. It is also the name other learners see in the message telling them to finish this workshop before they can start another one.', unused: false },
  { key: 'workshoptype', label: 'Workshop type', group: 'Enrollment page', hint: 'Only labels the workshop for your team — how it behaves for learners is set on the Settings tab. Required before this page can be saved.', detail: 'The app itself never reads this choice — it names the workshop in the admin workshops list, and it must be set before the Enrollment page will save. Everything a learner experiences comes from the Settings tab instead: a live workshop enforces its registration window and refuses sign-ups outside it; an evergreen one drops that window so anyone can start any time, runs on a per-person day count with a days-left badge, and holds a second one in a queue until the current one is finished; a CP workshop makes each person pick a focus group right after enrolling and only then shows content filtered to that group. This choice overrides those settings when the list picks a label, so if the two disagree the list will describe the workshop wrongly.', unused: true },
  { key: 'active', label: 'Active', group: 'Settings', hint: 'Has no effect in the app today — Workshop Active Web controls visibility. Turning it on still locks ordering and dates on Challenges.', detail: 'Nothing in the learner experience reads this any more — the workshops list, the home programmes row, the home banner and the older workshop page were all moved onto Workshop Active Web, and the old check sits commented out beside it. It is not inert on this admin screen though: while it is on, the Challenges tab locks set and activity reordering and freezes the unlock dates. This was verified against the web build only; the mobile app decides workshop visibility with a different setting that is not edited here.', unused: true },
  { key: 'activeparticipants', label: 'Active Participants Only', group: 'Settings', hint: 'Blocks enrollment for members whose subscription has lapsed — they see a "Subscription Expired" message when they tap Enroll.', detail: 'The last of the four checks, run after the new-users, journey and tier ones. Workshop-only sign-ups skip it, and so does anyone whose account carries no subscription status at all — only a recorded status that is not active will block. The workshop stays visible either way; only the Enroll tap is refused.', unused: false },
  { key: 'evergreenWorkshop', label: 'Always-on (evergreen) workshop', group: 'Settings', hint: 'Lets people start any time and run on their own countdown, not one shared start and end date. Set the day count too, or access never ends.', detail: 'With this on, the app stops checking the registration and workshop dates and instead counts each learner\'s access from the day they enrol, showing a days-left countdown and closing the workshop when their days run out — but only if you also set how many days each learner gets; leave that empty and access never expires and no countdown appears. It is also the master switch for the price card, the referral-code box and the extra list of who may enrol: those appear only on an always-on workshop, while the tier, journey and new-user eligibility rules keep working on dated workshops as normal. One more thing to expect: a learner who is still part-way through another always-on workshop gets this one queued with a Start button instead of immediate access.', unused: false },
  { key: 'evergreenWorkshopMeta', label: 'Always-on settings', group: 'Settings', hint: 'Sets how long each learner keeps access, counted from their own start date. The daily messages here are not shown anywhere in the app.', detail: 'Only the number of days reaches learners: counted from each person\'s own start date, it drives the "days left" badge on the card and progress bar, and swaps the workshop for the congratulations screen when it runs out — even if they finished every activity days earlier. The daily messages are never shown in the app, and the last-activity message is only sent by the retired old workshop screen, not the one participants use today. All of this applies only when the workshop is set to run as always-on.', unused: false },
  { key: 'categorybased', label: 'Category based', group: 'Settings', hint: 'Turns this into a focus-group workshop: participants pick a focus group before starting, then see only that group\'s challenges. Set the focus groups up first and assign every challenge to one, or participants are locked out or see an empty workshop.', detail: 'With this on, enrolling does not open the workshop straight away — the participant is held on a step they cannot dismiss, where they watch the intro video and choose one focus group, and only then do the challenges open. From then on they see only the challenges assigned to their chosen group, so any challenge left unassigned is invisible to them; and if no focus groups are set up (or they cannot be found), the participant is stopped with a "Focus Groups Unavailable" message and cannot get into the workshop at all. Facilitators and cohort members skip the choice and see every group\'s challenges, and these workshops never show the big end-of-workshop congratulations page — someone who finishes their group gets a smaller "Outstanding Achievement" note inside the workshop instead.', unused: false },
  { key: 'categorythumbnail', label: 'Category thumbnail', group: 'Settings', hint: 'The still image the play button sits on for the intro video in the focus-group step. Shown only if a category video is set.', detail: 'In a workshop that uses focus groups, learners see this image with a play button above the list of groups, and tapping it plays the intro video full screen with the same image held on screen while it loads. With no category video set it is not shown at all; with a video but no image, the play button sits on a plain coloured block. Facilitators and cohort members skip the focus-group step entirely, so they never see it.', unused: false },
  { key: 'categoryVideo', label: 'Category video', group: 'Settings', hint: 'Shown above the focus-group list when a participant starts the workshop, to watch before they pick a group.', detail: 'When set, the focus-group step opens with a heading telling the participant to watch before choosing, plus a tappable preview tile — the Category thumbnail image, or a plain dark panel when none is set — that opens the video full screen. Leave it empty and the whole block disappears, so the participant goes straight to the list of groups. Watching is never enforced, and facilitators and cohort members skip this step altogether, so they never see this video.', unused: false },
  { key: 'selectedgroup', label: 'Chat group', group: 'Settings', hint: 'Enrolling adds the participant to this group chat, which then appears in their Support area. Paid sign-ups are not added to it.', detail: 'On a free or referral-code enrolment the person is added to the chosen group immediately, and the conversation appears under Chats in the app\'s Support area. Participants who pay through checkout are enrolled by the server and are not joined, so a paid workshop will not fill the group this way. Pick a group conversation that still exists and has not been deleted, or the enrolment still succeeds and the person simply never sees the chat; leave it empty to skip auto-joining.', unused: false },
  { key: 'cohortcategoriesforthisworkshop', label: 'Cohort categories', group: 'Settings', hint: 'Only used when the workshop runs with focus groups: it records a group against cohort members, who skip the group picker either way. Only the first one counts.', detail: 'Cohort members never see the focus-group choice — belonging to one of this workshop\'s cohorts is what skips it — so this setting only decides which group gets recorded against them. It changes nothing they see: cohort members are shown every group\'s challenges regardless of what you pick here, and leaving it empty simply records no group for them. Only the first entry is ever used, and none of this applies unless the workshop is set to run with focus groups.', unused: false },
  { key: 'cohortsforthisworkshop', label: 'Cohorts', group: 'Settings', hint: 'Members of these cohorts skip the focus-group choice when they enroll and see every group\'s challenges, with their own welcome message.', detail: 'Only takes effect while Category based is on. Membership is re-checked against each cohort\'s participant list every time the learner opens the workshop, so adding someone later opens up every group\'s challenges on their next visit, though facilitator-only content still stays hidden from them; the welcome they get in place of the picker is the Above Diagnostics one, and it is only ever shown at the moment they enroll. Emptying this list does not take the wider view back from people already enrolled as cohort members — removing them from the cohort itself does.', unused: false },
  { key: 'enrolledcongrats', label: 'Congratulations message', group: 'Settings', hint: 'The wording inside the celebration pop-up that appears as soon as someone enrols. Leave blank to use the standard message.', detail: 'Right after a successful enrolment a pop-up appears that can only be closed with its single "Let\'s begin" button, and this text is the body of it; the heading and the button wording are fixed, and leaving it blank shows the standard "you\'ve successfully enrolled" copy. Anyone who is put in the queue behind a workshop they are still doing sees a fixed waiting message instead, so this wording never reaches them. Where the workshop asks people to pick a focus group, that button leads to the focus-group choice before the workshop itself.', unused: false },
  { key: 'evergreenWorkshopMeta.workshopDays', label: 'Days of access', group: 'Settings', hint: 'Only for evergreen workshops: how many days each learner keeps access after enrolling, shown to them as a days-left countdown.', detail: 'Counted from each learner\'s own enrolment day, so everyone gets the same length of access whenever they join; when it runs out they are moved to the congratulations page and can no longer open activities, unless that person has been given a personal extension, which only ever lengthens access. Finishing every activity early does not end an evergreen workshop — the learner stays in it until the days run out. Left empty or zero there is no countdown and it only ends when you mark the workshop complete, and it has no effect at all on a workshop that is not set to run as evergreen.', unused: false },
  { key: 'loginlogchannel', label: 'Default and new-user log channel', group: 'Settings', hint: 'Has no effect in the app today — nothing a participant sees depends on this value.', detail: 'The learner app never reads this setting, so changing it will not alter anything a participant sees or does. The app does write a sign-in record of its own, but that record is not tied to any particular workshop and carries no channel choice. Where those sign-in notices end up being posted is decided outside the app.', unused: true },
  { key: 'facilitatorprofiles', label: 'Facilitators', group: 'Settings', hint: 'The people running this workshop: they skip choosing a focus group and see every challenge and activity, including facilitator-only ones. Only has an effect when Workshop Facilitator and Category Based are both on.', detail: 'With Workshop Facilitator and Category Based both on, anyone listed here gets the facilitator welcome message instead of the focus-group chooser, then enters unfiltered and sees every challenge and activity, including the ones marked Facilitators only. The list is re-checked each time they open the workshop, so adding or removing someone changes what they see straight away, even after they have enrolled. Being listed grants no enrollment privileges — they pass or fail the same access rules as everyone else — and with Category Based off there is no focus-group step to skip, so the list has no effect there.', unused: false },
  { key: 'evergreenWorkshopMeta.lastChallengeMessage', label: 'Final activity message', group: 'Settings', hint: 'The notification a learner gets when they finish the last activity of an always-on workshop. It is skipped if that activity is one they submit.', detail: 'It fires only on always-on workshops, and only when the learner clears the final activity by tapping through — if that last activity is an assignment they submit, the message is never sent. Trailing notes and live-call steps are not counted as activities here, so it can arrive while those are still ahead. Only the older workshop screen sends it, so learners on the current screen never receive it, and leaving it blank sends the notification with no text.', unused: false },
  { key: 'evergreenaccessto.selected', label: 'Hand-picked people', group: 'Settings', hint: 'These people enrol free on an evergreen workshop, and they skip the tier requirement on any workshop.', detail: 'On a workshop that runs as evergreen, anyone listed here enrols free and is never shown the price card, even when the workshop is not open to all existing members. The list also overrides the tier requirement everywhere: a listed person passes the tier check on any workshop, evergreen or not, while the remaining eligibility checks still apply. It does not admit people who joined through a workshop sign-up (they follow the new sign-up switch instead), and on a workshop that is not evergreen it grants no free enrolment at all.', unused: false },
  { key: 'heroAccent', label: 'Hero accent colour', group: 'Settings', hint: 'Tints this workshop\'s card in the featured programmes row on Home. That card only appears for evergreen workshops with the home screen widget switched on.', detail: 'It colours the card\'s glow and background tint, the outcome stat boxes, the tag outlines, the bullet dots and the Enroll or Continue button, both on Home and on that row\'s View All page. Leave it blank and the app picks a colour automatically from a rotating set; anything that is not a valid hex colour is ignored the same way. It does not change the big hero banner or the workshop\'s own page.', unused: false },
  { key: 'heroDescription', label: 'Hero description', group: 'Settings', hint: 'The smaller supporting line under the banner headline — two lines on phones, three on larger screens.', detail: 'Sits between the headline and the banner\'s button. It is trimmed with an ellipsis past two lines on a phone and three on tablet or desktop, so put the promise first. It only matters while the workshop is featured in the banner.', unused: false },
  { key: 'heroHeading', label: 'Hero heading', group: 'Settings', hint: 'The bold headline on the home-screen banner, cut off after two lines.', detail: 'Appears in large bold type over the artwork on tablet and desktop, and directly under the artwork on phones. Anything past two lines is trimmed with an ellipsis, so keep it punchy. It only matters while the workshop is featured in the banner.', unused: false },
  { key: 'heroshowtype', label: 'Hero type', group: 'Settings', hint: 'Has no effect — the banner always shows the artwork and plays the clip over it whenever one is uploaded.', detail: 'The app never reads this choice. The artwork is always drawn first and, if a clip has been uploaded, it plays on top of it regardless of whether Image or Video is selected. To get a still banner, remove the clip rather than switching this to Image.', unused: true },
  { key: 'heroVideo', label: 'Hero video', group: 'Settings', hint: 'Plays silently on a loop over the home banner artwork; viewers tap the speaker icon for sound. Only works if this workshop is set to appear as a home banner.', detail: 'The clip is only ever loaded for workshops that are switched on to appear in the home page banner — on any other workshop it does nothing, and it never appears on the workshop page itself. It starts muted when its banner slide comes into view and loops from there until a viewer taps the speaker icon, which turns the sound on for every banner clip, not just this one. The banner artwork sits underneath, so it is what people see while the clip loads and what stays on screen if the clip fails to play.', unused: false },
  { key: 'referralmessage', label: 'Invite message', group: 'Settings', hint: 'Shown at the top of the invite when a member shares this workshop with their referral code, above the code and the link. Only used when the workshop is set up for referrals.', detail: 'It opens the referral invite produced by the share button on the home banner, the workshop card, the enrollment page and inside the workshop; the referral code line, a standard invitation line and the link are added underneath automatically, so write only the personal pitch here. That share button appears only when the workshop is set up for referrals and is not marked complete, and on evergreen workshops only for the members you allow to refer — on any other workshop this text is never seen. The plain link-share button carries its own separate message, so changing this one does not affect it; left blank, the invite simply goes out without a pitch line.', unused: false },
  { key: 'journeybased', label: 'Journey Based', group: 'Settings', hint: 'Limits who can enroll to people whose current journey is one you pick here; anyone else is told their journey is not allowed.', detail: 'The check happens when someone taps Enroll: if their current journey is not one you picked, or no journey is recorded for them, they are stopped with "Contact Admin — Your journey is not allowed for this workshop." People who signed up for workshops only are exempt and can still enroll. Leaving this on without picking any journeys blocks every other participant, and either way the workshop still shows up normally in the list until they tap Enroll.', unused: false },
  { key: 'selectedjourneys', label: 'Journeys', group: 'Settings', hint: 'Only used when Journey Based is on — a person can enroll only if their current journey is on this list. Workshop-only sign-ups skip this check.', detail: 'When someone taps Enroll, the app checks their current journey against this list and refuses them with a "Contact Admin" message if it is not there; a person with no journey set is refused too. People who signed up for workshops only bypass this check entirely, so an empty list with Journey Based on stops every other participant but still lets those sign-ups in. It never hides the workshop — blocked people still see it and only hit the wall when they tap Enroll — and with Journey Based off the list is stored but changes nothing.', unused: false },
  { key: 'paymentmap.hint', label: 'Line under the price', group: 'Settings', hint: 'A short line printed under the price, such as "One-time payment, lifetime access". It only shows where the learner is asked to pay or enter a coupon.', detail: 'Purely descriptive — it changes nothing about what is charged or who may buy. It appears only on the pay-or-coupon enrollment card, which the app shows on evergreen workshops when the learner is actually offered payment or a referral code and does not already have free access; anywhere else the text never appears at all. Left blank, no line is drawn under the price — there is no default wording to fall back on.', unused: false },
  { key: 'webactive', label: 'Live on the app', group: 'Settings', hint: 'Turns the workshop on for learners in the web app — the workshops list, the home banner and the home programmes row. Test mode can still show it to your listed testers while this is off.', detail: 'This is the live switch for the web app: with it on, the workshop can appear in the workshops list, in the home banner and in the home programmes row (the last two also need the workshop to be set up for those spots). With it off those entry points drop it, but test mode still shows it to the testers you list, and a finished workshop still shows in the list to people already enrolled. It controls discovery, not access — the current workshop page still opens for anyone holding a direct link while this is off; only the older workshop page turns visitors away.', unused: false },
  { key: 'eiflixmobileactive', label: 'Workshop EiFlix Mobile', group: 'Settings', hint: 'The workshop also runs in the EiFlix mobile app. It appears there only when this is on \u2014 the web switch above does not control the mobile app.', detail: 'Publishes this workshop inside the EiFlix mobile app, separately from the web switch above: a workshop can be live on one and hidden on the other, so both need turning on to reach everyone. Note the mobile app has to be reading this switch for it to take effect \u2014 confirm with the app team before relying on it for a launch.', unused: false },
  { key: 'mailTemplate', label: 'Mail template', group: 'Settings', hint: 'No effect inside the app — nothing a participant sees on screen is built from this wording.', detail: 'The learner app never reads the subject, description or live-call text, so no screen reflects them. If an enrolment e-mail goes out with this wording it is assembled by back-end automation outside the app, and nothing in the app confirms or displays it.', unused: true },
  { key: 'enrollmentnotallowedmessagenew', label: 'Message when a new sign-up can\'t enrol', group: 'Settings', hint: 'What a new sign-up sees instead of enrolling when an evergreen workshop\'s access settings don\'t let new sign-ups in.', detail: 'Shown as a "Currently Unavailable for You" pop-up when the person taps Enroll — the same pop-up as the existing-member message, but only for people who are new to the app and not yet members. It only ever appears on a workshop set to run as evergreen that restricts who may join; on any other workshop this text is never used. It also covers the case where new sign-ups are allowed in but the paid or referral offer is limited to existing members, since they then have nothing on the page to act on. Left blank they get a bare "Enrollment is not available."', unused: false },
  { key: 'enrollmentnotallowedmessage', label: 'Message when an existing member can\'t enrol', group: 'Settings', hint: 'The explanation an existing member sees when they tap Enrol on an evergreen workshop that is not open to them.', detail: 'Only appears on evergreen workshops that restrict who may join — on any other workshop this text is never shown — and it comes up in a pop-up headed "Currently Unavailable for You". The Enrol button is deliberately left visible so people can see the workshop exists and read why they cannot join, so this text is worth writing carefully; left blank they get a bare "Enrollment is not available." Brand-new members see their own separate message instead, and an existing member who is being offered payment or a referral code gets that offer rather than this pop-up.', unused: false },
  { key: 'heromobile', label: 'Mobile hero active', group: 'Settings', hint: 'Has no effect — the home banner on phones is driven by the Web hero active switch beside it, not by this one.', detail: 'The app never reads this switch, on any device. Phones, tablets and desktop all follow the same rule: a workshop reaches the home banner only when Web hero active is on AND the workshop is live on the web — or it is in test mode and the viewer is on its test-user list. Turning this switch on or off changes nothing the learner sees.', unused: true },
  { key: 'heroeiflixmobile', label: 'EiFlix mobile hero active', group: 'Settings', hint: 'Turn this on and the hero banner shows in the EiFlix mobile app. The web hero switch beside it does not control the mobile app.', detail: 'Publishes this workshop\u2019s hero banner inside the EiFlix mobile app, separately from the web hero switch \u2014 the two are independent, so a banner can run on one and not the other. The heading, description, artwork and clip below are shared by both. Note the mobile app has to be reading this switch for it to take effect; confirm with the app team before relying on it.', unused: false },
  { key: 'heroImageMobile', label: 'Mobile hero image', group: 'Settings', hint: 'Has no effect in the app today — phones show the same picture as the main hero image, so nothing uploaded here is ever displayed.', detail: 'The app never reads this image. On a phone the banner shows the main hero picture at its full wide shape, with the heading, description and buttons in a block underneath it rather than on top of the art. Uploading a separate portrait version here will not change what anyone sees.', unused: true },
  { key: 'newusersonly', label: 'New Users Only', group: 'Settings', hint: 'Only people whose account was created just for workshops can enroll; everyone else is told they are not eligible and to contact admin.', detail: 'When this is on, only accounts created just for workshops can enroll; anyone else who taps Enroll gets "You\'re not eligible - Please contact admin.", including someone who signed up recently through the main app. Those people also skip the journey and subscription requirements, but the tier requirement still applies to them, so pairing this with a tier restriction can still lock them out. It never hides the workshop - the card and the detail page stay visible to everyone, only the Enroll tap is blocked.', unused: false },
  { key: 'evergreenaccessto.all', label: 'Open to all existing members', group: 'Settings', hint: 'Only applies to evergreen workshops: existing members enrol free with no price or invite code, if they already pass the other entry rules.', detail: 'This covers existing members only — people who signed up but are not members yet are governed by their own switch instead. Members must still clear the workshop\'s other entry rules first (tier, journey, active subscription), so switching this on does not let a tier-restricted member in; only hand-picking them does that. While it is on, admitted members always enrol free and are never shown the price or invite-code card; with it off they must be hand-picked or buy in, otherwise they get the "unavailable" message.', unused: false },
  { key: 'evergreenaccessto.new', label: 'Open to new sign-ups', group: 'Settings', hint: 'Has no effect in the app today: someone who signed up through a workshop sign-up sees the same thing whether this is on or off.', detail: 'On or off, a person who signed up through a workshop sign-up sees the same thing: the price and invite-code card when this workshop offers a paid or invite-code way in, and the "currently unavailable" message when it offers neither. They never get free access from this section — the "all existing members" and hand-picked settings do not apply to them, and the older workshop page ignores this section completely. Watch the side effect instead: on an evergreen workshop that had no access settings at all, saving any of them switches it from open to everyone to admitted people only.', unused: false },
  { key: 'paymentmap.amountstriked', label: 'Original price', group: 'Settings', hint: 'Shown crossed out beside the price on the workshop page and drives the percentage-off badge; only ever appears on evergreen workshops.', detail: 'On an evergreen workshop it appears crossed out beside the price on the enrollment card, and above the price on the home screen\'s featured program card; on any other workshop it has no effect at all. The percentage-off badge on the enrollment card is worked out from the two prices, so there the crossed-out price and the badge only show when this is higher than the amount actually charged, while the home card shows it crossed out whenever it is filled in. It is display only — nobody is ever charged this amount, and leaving it blank simply hides the crossed-out price and the badge.', unused: false },
  { key: 'payment', label: 'Paid enrolment', group: 'Settings', hint: 'Puts a price card with a pay button on the workshop page, in place of the usual join button, so people pay to enrol.', detail: 'The card shows the amount, any struck-through price and discount badge, and a button that takes the payment and enrols the person on success. Existing people you have already given access to — through All users have access or the people picker — never see it and join free, but new people still see the price card even when New users have access is on. Payment for decides who is offered it; for existing people, Payment based on customer status takes over from that choice completely, so a match is offered payment even if Payment for excludes them and a non-match is offered none, while Payment based on financial status has no effect in the app today.', unused: false },
  { key: 'paymentmap.amount', label: 'Price', group: 'Settings', hint: 'The amount the learner actually pays, shown big on the workshop\'s payment card, on the Enroll button and on the home programme cards. Type digits only — the rupee symbol and commas are added for you.', detail: 'This is the figure charged at checkout, and the app formats it for display, so entering a currency symbol yourself shows a doubled symbol on the workshop page. Anything other than plain digits also hides the discount badge and the struck-through original price. Leaving it blank is not safe: the page then shows the older price set elsewhere on this workshop, but the charge is still taken from the payment settings.', unused: false },
  { key: 'paymentmap', label: 'Pricing', group: 'Settings', hint: 'Sets the price people see: the amount charged, the crossed-out comparison price, who the offer is for, and the small line under it.', detail: 'On an always-on workshop this becomes the price block that replaces the Enroll button, shown to anyone who can pay or enter a referral code and never to someone who already has free access; the amount also appears on the home-screen card for workshops featured there. The audience choice here decides who is actually offered payment, and on a referral workshop it also hides the coupon field from anyone outside that audience. The crossed-out price and its discount badge appear only when it is higher than the amount charged, and the server works the real charge out from that same amount.', unused: false },
  { key: 'qanda', label: 'Q&A discussion', group: 'Settings', hint: 'Gives enrolled participants a question thread where they can ask the group and reply to each other.', detail: 'With it on, a chat button appears in the workshop\'s top bar for enrolled participants and opens a live thread split into "Your questions" and "Community", each expandable to its replies; a Q&A notification also opens straight into that thread. With it off, the button is hidden, and on the older workshop page the Q&A tab reads "Q&A feature is not enabled for this workshop".', unused: false },
  { key: 'referralcodestartswith', label: 'Referral code prefix', group: 'Settings', hint: 'The letters every invite code for this workshop starts with. Type it in capitals - a lower-case prefix makes codes impossible to redeem.', detail: 'Each person\'s code is this prefix plus a few characters from their account and four random letters, so codes for this workshop are recognisable at a glance. Codes are always matched in capitals when someone redeems one or opens a shared link, so a prefix containing lower-case letters produces codes that can never be accepted. Leaving it empty is fine - codes still work, just with no prefix - and the prefix is fixed into a person\'s code the first time they share, so a later change only affects people who have not shared yet.', unused: false },
  { key: 'referralworkshop', label: 'Referral workshop', group: 'Settings', hint: 'Turns on invite sharing: eligible people get a Share button carrying their own code. Joining free with a code works only on evergreen workshops.', detail: 'A Share button appears on the workshop card, the home banner and the participant screen for as long as the workshop is unfinished, and it sends the sharer\'s personal invite code plus a link that pre-fills it. On an evergreen workshop that button is narrowed to the people you list as allowed referrers, and only there does a second Share button sit beside Enrol on the workshop page. The box where an invitee types a code and enrols free exists only on the evergreen enrolment card, so on a non-evergreen workshop this setting spreads invites that nobody can redeem; even on evergreen it is hidden from anyone the paid-offer audience excludes and from anyone already granted free access.', unused: false },
  { key: 'categoriesforthisworkshop', label: 'Selected categories', group: 'Settings', hint: 'Only matters when the workshop asks people to choose a focus group — these are the options they pick from, in this order. The choice is final.', detail: 'After enrolling, the learner gets a screen they cannot dismiss listing these groups in this order, each as a card with its name and short description, and must pick one before the workshop opens; the pick cannot be changed later. Any group whose record cannot be found is quietly left out, and if none of them can be found the learner is blocked with an error and cannot enter at all, so an empty or broken list strands everyone who enrolls. Ordinary participants then only see challenges tagged with the group they chose, so a challenge tagged with none of these is hidden from all of them, though facilitators and cohort members still see everything.', unused: false },
  { key: 'enableshare', label: 'Share button', group: 'Settings', hint: 'Adds a Share button that hands out this workshop\'s own link — on its page, in the home banner and on the home programmes card.', detail: 'The button shares the workshop\'s page address tagged with the sharer\'s profile, so the referral can be traced back, and copies that link to their clipboard at the same time. On the home banner and the home programmes card it is shown to signed-in visitors only. It is separate from the referral share icon on the workshops list cards, which currently ignores this setting completely.', unused: false },
  { key: 'enablesharemessage', label: 'Share message', group: 'Settings', hint: 'Optional line of text placed above the link when someone shares this workshop. Only used when Enable Share is on.', detail: 'When filled in, this sentence sits above the workshop link in the message the person sends; leave it empty and just the bare link goes out. It does not apply to the separate referral share (the "Share the Gift" button), which has its own message. Only the link itself is copied to their clipboard — the wording travels with the share targets, not the copy.', unused: false },
  { key: 'referraldialogmessage', label: 'Share pop-up message', group: 'Settings', hint: 'Has no effect in the app today — the Share button goes straight to the sharing options, with no pop-up showing this text.', detail: 'A pop-up that would have shown this text before sharing exists in the code but is never opened, so anything entered here is saved and ignored. On desktop the Share button does open a sharing window, but it only lists the sharing targets and the link — the wording that actually goes out with a share comes from Referral message.', unused: true },
  { key: 'homescreenwidget', label: 'Show on the home screen', group: 'Settings', hint: 'Adds this workshop to the featured programmes row on the app home screen. Needs Workshop Active Web and Evergreen Workshop both on.', detail: 'The row only picks up workshops that have Workshop Active Web on (or Workshop Test Mode, and then only for the people listed as test users), Evergreen Workshop on, and this switch on - Workshop Active on its own is not enough, and a workshop marked completed is never advertised there. The card shows the hero image, title, short description, the outcome stats, the who-it\'s-for points and the price with an Enroll button; anyone already enrolled sees Continue instead of the price. The same workshops also fill the View All page behind that row.', unused: false },
  { key: 'breakdown', label: 'Show participant progress', group: 'Settings', hint: 'Adds member counts to each activity: how many have finished it, and how many have not yet. Only the older workshop page shows these.', detail: 'On the older workshop page, each unfinished activity gets a red badge counting everyone who has not completed it yet — it reads "Active", but it includes people who have never opened the activity, and it counts the viewer too — alongside a count of members who have finished; once the participant completes it themselves, that finished count turns green. Both numbers stay at zero until the activity\'s own start date and time has passed, people who enrolled but never started are left out, and live-call activities show no counts at all. The current workshop experience ignores this setting entirely, and the older page is reachable only by direct link, so in practice almost no participant sees any difference.', unused: false },
  { key: 'paymentmap.customerstatus', label: 'Subscription statuses that may pay', group: 'Settings', hint: 'On evergreen workshops this becomes the deciding rule for existing members: only those on a listed status are offered the Pay option.', detail: 'Has no effect unless the workshop runs as evergreen and paid purchase is switched on. Once you list anything here it replaces the audience setting for existing members: a member whose status matches is offered the Pay option even if the audience or the allowed-to-enrol list would have excluded them, while a member whose status does not match gets no Pay option at all and falls back to the ordinary enrolment outcome. It never applies to new sign-ups, never opens the invite-code box, and members who already have free access still enrol free rather than seeing a price. Leave it empty to use the audience setting alone.', unused: false },
  { key: 'testmode', label: 'Test mode', group: 'Settings', hint: 'Limits the workshop to the people in the Test users list, so they can preview it before it goes live. Everyone else stops seeing it, even if it is already live.', detail: 'The people in the Test users list see the workshop in the workshops list and in the programmes row on Home even while it is not live; with test mode on nobody else sees it there, and if that list is empty no one sees it at all. Two exceptions to watch: a workshop that is live and in test mode at the same time still shows its Home banner to everyone, and anyone holding a direct link can still open the workshop page. On the older workshops list the card also carries an orange Test Mode badge, and the older page sends non-testers back to the list.', unused: false },
  { key: 'testusers', label: 'Test viewers', group: 'Settings', hint: 'While test mode is on, only these people still see the workshop where it is listed. It hides the listing, not the page — a direct link still opens it.', detail: 'Only consulted while test mode is on, and matched against the viewer\'s own profile: anyone not on this list stops seeing the workshop in the workshop list and in the home page\'s programme row, so test mode with an empty list hides it from everyone in those places. It filters those listings only — the workshop\'s own page still opens for any signed-in person who has the link. And if the workshop is also live and set as the featured banner, that banner keeps showing to everyone, signed-out visitors included.', unused: false },
  { key: 'tierbased', label: 'Tier Based', group: 'Settings', hint: 'Only people holding one of the tiers you pick can enroll, workshop-only sign-ups included; pick no tiers and nobody can enroll.', detail: 'The check runs when someone taps Enroll, so the workshop still appears in the lists and its page still opens — this restricts joining, not browsing. Unlike the journey and subscription restrictions it is never waived for workshop-only sign-ups, and leaving the tier list empty blocks everyone; the one way past it is naming a person on the hand-picked access list used for evergreen access, which skips this check alone and only on the current app screen. Blocked people are told "This is an Exclusive Workshop. Please upgrade your journey to access." — on the older screen with an Upgrade Now button that raises a support ticket, on the current screen as a plain message.', unused: false },
  { key: 'selectedtiers', label: 'Tiers', group: 'Settings', hint: 'Only people holding one of these tiers can enroll. Used only when Tier Based is on, and leaving it empty locks everyone out.', detail: 'When someone taps Enroll they get in if any tier on their record is in this list; hold none of them and they are stopped with an "Upgrade to Access!" message. The check happens only at that moment, so the workshop still appears normally in the list, and it applies to every participant with no exception for workshop-only people. Anyone hand-picked in the People with access list skips this check completely and can enroll holding no tier at all.', unused: false },
  { key: 'triggerFunction', label: 'Trigger function', group: 'Settings', hint: 'Has no effect in the app today — nothing in the learner experience reads it.', detail: 'A case-insensitive search of the entire app source finds no reference to this setting, in either the current or the older workshop experience. Changing it will not alter anything a learner sees. If it is doing anything at all, it is in a background process outside the app.', unused: true },
  { key: 'refercount', label: 'Uses per referral code', group: 'Settings', hint: 'How many people can join free with one person\'s invite code before it stops working. Only applies when the workshop offers invite codes.', detail: 'Each sharer gets their own code with its own counter, so this is a per-person limit rather than a workshop total, and anyone who redeems one enrols without paying. The limit is checked at the moment someone redeems, so a change applies immediately to codes already shared — lowering it below what a code has already given out retires that code at once. Left empty or at zero no code will ever work, and the invite path is not offered at all unless the workshop is set up to use invite codes.', unused: false },
  { key: 'hero', label: 'Web hero active', group: 'Settings', hint: 'Turn on to feature this workshop in the large rotating banner at the top of the home screen, on web and mobile alike.', detail: 'The workshop only reaches the banner if it is also live on the web, or in test mode with the viewer listed as a test user. Banners rotate every five seconds and the button takes the viewer straight to this workshop\'s enrolment page. Despite the wording, this single switch controls the banner on every device — the mobile switch beside it is never read.', unused: false },
  { key: 'heroImage', label: 'Web hero image', group: 'Settings', hint: 'The wide banner picture used where this workshop is featured on the home screen, and on its tile in a buyer\'s Purchases list. It only shows there when the workshop is also switched on as a home banner or home-screen feature.', detail: 'It appears in three places: the big rotating banner at the top of the home screen (only for workshops switched on as a banner and visible on the web), the card in the featured programmes row (only for evergreen workshops switched on to show on the home screen and not yet marked completed), and the workshop\'s tile in the Purchases list on a buyer\'s profile. Use a very wide banner-shaped picture, roughly 2.8 times wider than tall, since squarer artwork gets trimmed and tablets shave a little off the top and bottom. It is not used on the workshop\'s own page or in the regular workshop list, and if it is left blank the home banner shows a grey broken-image icon in its place.', unused: false },
  { key: 'cpwelcomemessage', label: 'Welcome messages', group: 'Settings', hint: 'Replaces the focus-group picker for facilitators and cohort members: the Facilitators text for one, Above Diagnostics for the other.', detail: 'Only applies to workshops that use focus groups; regular participants never see either message, because they get the focus-group picker instead. Facilitators and members of the chosen cohorts get this pop-up once, the first time they enter after enrolling, and cannot get past it without tapping Start Immersing. The Facilitators version only reaches someone when Workshop Facilitator is on and their profile is in the Facilitators list; your formatting is kept, and leaving the heading empty does not switch the pop-up off — it simply shows a plain "Welcome".', unused: false },
  { key: 'enrollwattimessage', label: 'WhatsApp enrol message', group: 'Settings', hint: 'No effect in the app today — nothing you type here is shown to participants or sent to them anywhere.', detail: 'The learner app never reads this text, so it appears on no screen and nothing in the app sends it when someone enrols. The value is still saved with the workshop, so leaving it filled in does no harm — it simply does nothing. To change what a participant sees immediately after enrolling, use the Congratulations message instead.', unused: true },
  { key: 'evergreenaccessto', label: 'Who can enrol', group: 'Settings', hint: 'Decides who joins an always-on workshop free, who is shown the price or invite-code card instead, and who is turned away. Left empty on an invite-code workshop, nobody gets in free.', detail: 'On an always-on workshop this is read as the page loads and again on the Enrol tap: anyone it admits joins free and is never shown a price, anyone it does not admit gets the price and invite-code card when the offer covers them, and otherwise the matching "not available" message. Brand-new users are judged only by its new-user part, so admitting everyone still does not let them in free. Hand-picking a person also lets them past the membership-tier restriction, on any workshop; leaving the whole setting empty opens a plain always-on workshop to everyone, but on an invite-code workshop it grants nobody free entry.', unused: false },
  { key: 'referallowedusers', label: 'Who can send invites', group: 'Settings', hint: 'Decides who sees the Share button here: all existing users, new users, or only the people you pick. Only works with Referral Workshop on.', detail: 'Nothing chosen here has any effect unless Referral Workshop is on — that toggle is what creates the Share button in the first place, on the workshop card, the home banner and the workshop page alike. New users are governed only by their own switch: turning on all existing users does not include them, and neither does adding them to the picked list. The picked list is read only while the all-users switch is off, and the button disappears for everyone once the workshop is completed or its evergreen run has ended.', unused: false },
  { key: 'paymentmap.paymentfor', label: 'Who the offer is for', group: 'Settings', hint: 'On evergreen workshops, limits the price card — the Pay button and the invite-code box — to new sign-ups, existing members, or everyone.', detail: 'Only has an effect on evergreen workshops; there, anyone outside the chosen audience sees no price card at all and gets the plain Enrol button instead, plus the blocked message if the workshop is not open to them. Restricting the offer to new sign-ups also hides the invite-code box from existing members, which is a common surprise; left unset, the offer goes to everyone. Two exceptions: if you list customer statuses for payment, those decide the Pay button for existing members instead of this setting, and a learner who already has free access never sees a price card.', unused: false },
  { key: 'workshopactivitychannel', label: 'Workshop activity log', group: 'Settings', hint: 'Has no effect in the app today — picking a channel here changes nothing a participant sees.', detail: 'The learner app never reads this setting, so no screen, message or notification in the app changes when you set it. If workshop activity is being posted to a team channel somewhere, that is done by back-end automation outside the app.', unused: true },
  { key: 'facilitator', label: 'Workshop Facilitator', group: 'Settings', hint: 'Lets the people you list as facilitators skip the focus-group step and see every activity, including facilitator-only ones. Works only in a category-based workshop.', detail: 'Switching it on does nothing on its own — someone counts as a facilitator only if they are also named in the facilitators list, and only in a workshop that asks participants to pick a focus group; anywhere else the app shows the same content to everyone, so activities marked facilitator-only are still visible to ordinary participants. A facilitator never picks a focus group: they see the facilitator welcome message instead and then get the whole workshop, every group\'s content plus the facilitator-only items. It is not an enrollment rule — a facilitator still has to pass the same new-user, journey, tier and active-subscription checks — and the role is re-checked live each time the workshop is opened, so adding or removing someone changes what they see even if they enrolled long ago.', unused: false },
];

/** Hint shown under a field, keyed by control name. */
export const FIELD_HINTS: { [key: string]: string } =
  FIELD_REFERENCE.reduce((m, f) => { m[f.key] = f.hint; return m; }, {} as { [k: string]: string });

/** Settings the user app does not read today. */
export const UNUSED_FIELDS: FieldNote[] = FIELD_REFERENCE.filter(f => f.unused);

